 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Uniform full rows/columns are separators between equal-sized panels.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    rb = [-1] + sep_rows + [h]
    cb = [-1] + sep_cols + [w]
    sep_colors = {grid[r][0] for r in sep_rows} | {grid[0][c] for c in sep_cols}
    freq = {}
    for row in grid:
        for v in row:
            if v not in sep_colors:
                freq[v] = freq.get(v, 0) + 1
    background = max(freq, key=freq.get)
    out = []
    for i in range(len(rb)-1):
        row = []
        for j in range(len(cb)-1):
            n = sum(grid[r][c] != background and grid[r][c] not in sep_colors
                    for r in range(rb[i]+1, rb[i+1])
                    for c in range(cb[j]+1, cb[j+1]))
            # A single mark takes the panel background color; a pair is encoded as 1.
            row.append(1 if n >= 2 else (background if n == 1 else 0))
        out.append(row)
    return out
